      { id: "p2-a7", questionNumber: 7, question: "Transformational leadership involves...", questionAf: "Transformasionele leierskap behels...", options: [{ label: "A", text: "Maintaining the status quo", textAf: "Die status quo te handhaaf" }, { label: "B", text: "Inspiring and motivating followers to achieve beyond expectations", textAf: "Volgelinge te inspireer en te motiveer om meer as verwag te bereik" }, { label: "C", text: "Punishing underperformance", textAf: "Swak prestasie te straf" }, { label: "D", text: "Delegating all decisions", textAf: "Alle besluite te delegeer" }], correctAnswer: "B", topic: "Leadership & Management", marks: 2 },
      { id: "p2-a8", questionNumber: 8, question: "A SETA is a...", questionAf: "'n SETA is 'n...", options: [{ label: "A", text: "South African Export Trading Agency", textAf: "Suid-Afrikaanse Uitvoerhandelsagentskap" }, { label: "B", text: "Sector Education and Training Authority", textAf: "Sektor Onderwys en Opleidingsowerheid" }, { label: "C", text: "Small Enterprise Tax Authority", textAf: "Kleinsake Belastingowerheid" }, { label: "D", text: "Standard Employment Terms Agreement", textAf: "Standaard Indiensnemingsvoorwaardes-ooreenkoms" }], correctAnswer: "B", topic: "Human Resources", marks: 2 },
      { id: "p2-a9", questionNumber: 9, question: "The King IV Report focuses on...", questionAf: "Die King IV-Verslag fokus op...", options: [{ label: "A", text: "Tax law", textAf: "Belastingreg" }, { label: "B", text: "Good corporate governance principles", textAf: "Goeie korporatiewe bestuursbeginsels" }, { label: "C", text: "Marketing ethics", textAf: "Bemarkingsetiek" }, { label: "D", text: "Environmental policy", textAf: "Omgewingsbeleid" }], correctAnswer: "B", topic: "Ethics, Professionalism & Corporate Governance", marks: 2 },
      { id: "p2-a10", questionNumber: 10, question: "The Employment Equity Act requires employers to...", questionAf: "Die Wet op Gelyke Indiensneming vereis dat werkgewers...", options: [{ label: "A", text: "Pay all workers equally", textAf: "Alle werkers gelyk betaal" }, { label: "B", text: "Promote equal opportunity and eliminate unfair discrimination", textAf: "Gelyke geleenthede bevorder en onbillike diskriminasie uitskakel" }, { label: "C", text: "Provide free housing", textAf: "Gratis behuising verskaf" }, { label: "D", text: "Reduce the retirement age", textAf: "Die aftree-ouderdom verlaag" }], correctAnswer: "B", topic: "Legislation", marks: 2 },
      { id: "p2-a11", questionNumber: 11, question: "Delegation as a management function means...", questionAf: "Delegering as 'n bestuursfunksie beteken...", options: [{ label: "A", text: "Doing everything yourself", textAf: "Om alles self te doen" }, { label: "B", text: "Assigning tasks and authority to subordinates", textAf: "Om take en gesag aan ondergeskiktes toe te wys" }, { label: "C", text: "Avoiding responsibility", textAf: "Om verantwoordelikheid te vermy" }, { label: "D", text: "Reducing staff numbers", textAf: "Om personeelgetalle te verminder" }], correctAnswer: "B", topic: "Leadership & Management", marks: 2 },
      { id: "p2-a12", questionNumber: 12, question: "Professional behaviour in the workplace includes...", questionAf: "Professionele gedrag in die werkplek sluit in...", options: [{ label: "A", text: "Coming late but working extra hours", textAf: "Om laat te kom maar ekstra ure te werk" }, { label: "B", text: "Being punctual, respectful and maintaining integrity", textAf: "Om stiptelik te wees, respek te toon en integriteit te handhaaf" }, { label: "C", text: "Socialising during work hours", textAf: "Om tydens werksure te sosialiseer" }, { label: "D", text: "Using company resources for personal use", textAf: "Om maatskappyhulpbronne vir persoonlike gebruik te benut" }], correctAnswer: "B", topic: "Ethics, Professionalism & Corporate Governance", marks: 2 },
      { id: "p2-a13", questionNumber: 13, question: "A grievance procedure is used when...", questionAf: "'n Grieweprosedure word gebruik wanneer...", options: [{ label: "A", text: "An employee wants a promotion", textAf: "'n Werknemer 'n bevordering wil hê" }, { label: "B", text: "An employee has a complaint about working conditions", textAf: "'n Werknemer 'n klagte oor werksomstandighede het" }, { label: "C", text: "The company needs to restructure", textAf: "Die maatskappy moet herstruktureer" }, { label: "D", text: "New products are launched", textAf: "Nuwe produkte bekendgestel word" }], correctAnswer: "B", topic: "Legislation", marks: 2 },
      { id: "p2-a14", questionNumber: 14, question: "Strategic management involves...", questionAf: "Strategiese bestuur behels...", options: [{ label: "A", text: "Day-to-day operational decisions", textAf: "Dag-tot-dag operasionele besluite" }, { label: "B", text: "Long-term planning to achieve organisational goals", textAf: "Langtermynbeplanning om organisasiedoelwitte te bereik" }, { label: "C", text: "Only financial management", textAf: "Slegs finansiële bestuur" }, { label: "D", text: "Crisis management only", textAf: "Slegs krisisbestuur" }], correctAnswer: "B", topic: "Business Strategies", marks: 2 },
      { id: "p2-a15", questionNumber: 15, question: "A learnership differs from an internship because it...", questionAf: "'n Leerlingskap verskil van 'n interskap omdat dit...", options: [{ label: "A", text: "Does not require any training", textAf: "Geen opleiding vereis nie" }, { label: "B", text: "Combines structured learning with practical experience towards a qualification", textAf: "Gestruktureerde leer met praktiese ondervinding kombineer na 'n kwalifikasie" }, { label: "C", text: "Is only for university graduates", textAf: "Slegs vir universiteitsgegradueerdes is" }, { label: "D", text: "Pays higher salaries", textAf: "Hoër salarisse betaal" }], correctAnswer: "B", topic: "Human Resources", marks: 2 },
      { id: "p2-a16", questionNumber: 16, question: "Ethics in business means...", questionAf: "Etiek in besigheid beteken...", options: [{ label: "A", text: "Doing what is profitable regardless of impact", textAf: "Om te doen wat winsgewend is ongeag die impak" }, { label: "B", text: "Making decisions based on moral principles of right and wrong", textAf: "Om besluite te neem gebaseer op morele beginsels van reg en verkeerd" }, { label: "C", text: "Following trends", textAf: "Om neigings te volg" }, { label: "D", text: "Only obeying the law", textAf: "Om slegs die wet te gehoorsaam" }], correctAnswer: "B", topic: "Ethics, Professionalism & Corporate Governance", marks: 2 },
      { id: "p2-a17", questionNumber: 17, question: "A strike is legal when...", questionAf: "'n Staking is wettig wanneer...", options: [{ label: "A", text: "Workers simply walk out", textAf: "Werkers net uitstap" }, { label: "B", text: "Proper procedures including notice have been followed", textAf: "Behoorlike prosedures insluitend kennisgewing gevolg is" }, { label: "C", text: "The employer approves it", textAf: "Die werkgewer dit goedkeur" }, { label: "D", text: "It happens during lunch breaks", textAf: "Dit tydens middagetes gebeur" }], correctAnswer: "B", topic: "Legislation", marks: 2 },
      { id: "p2-a18", questionNumber: 18, question: "A business plan is important because it...", questionAf: "'n Besigheidsplan is belangrik omdat dit...", options: [{ label: "A", text: "Guarantees success", textAf: "Sukses waarborg" }, { label: "B", text: "Provides direction and helps secure funding", textAf: "Rigting verskaf en help om befondsing te bekom" }, { label: "C", text: "Eliminates all risk", textAf: "Alle risiko uitskakel" }, { label: "D", text: "Is only needed for large companies", textAf: "Slegs vir groot maatskappye nodig is" }], correctAnswer: "B", topic: "Business Strategies", marks: 2 },
      { id: "p2-a19", questionNumber: 19, question: "The Basic Conditions of Employment Act (BCEA) covers...", questionAf: "Die Wet op Basiese Diensvoorwaardes (WBDV) dek...", options: [{ label: "A", text: "Company profit sharing", textAf: "Maatskappy winsdeling" }, { label: "B", text: "Working hours, leave and overtime conditions", textAf: "Werksure, verlof en oortydvoorwaardes" }, { label: "C", text: "International trade law", textAf: "Internasionale handelsreg" }, { label: "D", text: "Tax deductions", textAf: "Belastingaftrekkings" }], correctAnswer: "B", topic: "Legislation", marks: 2 },
      { id: "p2-a20", questionNumber: 20, question: "The democratic leadership style encourages...", questionAf: "Die demokratiese leierskapstyl moedig aan...", options: [{ label: "A", text: "Strict obedience without question", textAf: "Streng gehoorsaamheid sonder vrae" }, { label: "B", text: "Employee participation in decision-making", textAf: "Werknemerdeelname aan besluitneming" }, { label: "C", text: "Leader makes all decisions alone", textAf: "Leier neem alle besluite alleen" }, { label: "D", text: "No leadership involvement", textAf: "Geen leierskapbetrokkenheid nie" }], correctAnswer: "B", topic: "Leadership & Management", marks: 2 }
