      { id: "p3-a2", questionNumber: 2, question: "A franchise is best described as...", questionAf: "'n Franchise word die beste beskryf as...", options: [{ label: "A", text: "A government-owned business", textAf: "'n Regeringsbesigheid" }, { label: "B", text: "A business model where the franchisor grants rights to operate under its brand", textAf: "'n Besigheidsmodel waar die franchisegewer regte verleen om onder sy handelsmerk te bedryf" }, { label: "C", text: "A non-profit organisation", textAf: "'n Nie-winsgewende organisasie" }, { label: "D", text: "A type of cooperative", textAf: "'n Tipe koöperasie" }], correctAnswer: "B", topic: "Business Strategies", marks: 2 },
      { id: "p3-a3", questionNumber: 3, question: "Unfair discrimination in the workplace includes treating someone differently based on...", questionAf: "Onbillike diskriminasie in die werkplek sluit in om iemand anders te behandel op grond van...", options: [{ label: "A", text: "Job performance", textAf: "Werkprestasie" }, { label: "B", text: "Race, gender or disability", textAf: "Ras, geslag of gestremdheid" }, { label: "C", text: "Qualifications", textAf: "Kwalifikasies" }, { label: "D", text: "Years of experience", textAf: "Jare ondervinding" }], correctAnswer: "B", topic: "Legislation", marks: 2 },
      { id: "p3-a4", questionNumber: 4, question: "The purpose of a business insurance policy is to...", questionAf: "Die doel van 'n besigheidsversekeringsbeleid is om...", options: [{ label: "A", text: "Guarantee profit", textAf: "Wins te waarborg" }, { label: "B", text: "Transfer financial risk to an insurer", textAf: "Finansiële risiko na 'n versekeraar oor te dra" }, { label: "C", text: "Avoid paying tax", textAf: "Belasting te vermy" }, { label: "D", text: "Replace management", textAf: "Bestuur te vervang" }], correctAnswer: "B", topic: "Business Strategies", marks: 2 },
      { id: "p3-a5", questionNumber: 5, question: "Situational leadership means a leader should...", questionAf: "Situasionele leierskap beteken 'n leier moet...", options: [{ label: "A", text: "Always use the same style", textAf: "Altyd dieselfde styl gebruik" }, { label: "B", text: "Adapt their style based on the situation and team readiness", textAf: "Hul styl aanpas gebaseer op die situasie en span se gereedheid" }, { label: "C", text: "Only lead during crisis", textAf: "Slegs tydens krisis lei" }, { label: "D", text: "Follow rather than lead", textAf: "Volg eerder as om te lei" }], correctAnswer: "B", topic: "Leadership & Management", marks: 2 },
      { id: "p3-a6", questionNumber: 6, question: "The Consumer Protection Act gives consumers the right to...", questionAf: "Die Wet op Verbruikersbeskerming gee verbruikers die reg op...", options: [{ label: "A", text: "Free products", textAf: "Gratis produkte" }, { label: "B", text: "Return defective goods within 6 months", textAf: "Defekte goedere binne 6 maande terug te stuur" }, { label: "C", text: "Unlimited refunds", textAf: "Onbeperkte terugbetalings" }, { label: "D", text: "Set their own prices", textAf: "Hul eie pryse vas te stel" }], correctAnswer: "B", topic: "Legislation", marks: 2 },
      { id: "p3-a7", questionNumber: 7, question: "Corporate Social Responsibility (CSR) involves...", questionAf: "Korporatiewe Sosiale Verantwoordelikheid (KSV) behels...", options: [{ label: "A", text: "Only focusing on profit", textAf: "Om slegs op wins te fokus" }, { label: "B", text: "Voluntarily contributing to social and environmental wellbeing", textAf: "Vrywillig by te dra tot sosiale en omgewingswelstand" }, { label: "C", text: "Government mandated charity", textAf: "Regeringsmandaat liefdadigheid" }, { label: "D", text: "Reducing staff wages", textAf: "Personeellone te verminder" }], correctAnswer: "B", topic: "Ethics, Professionalism & Corporate Governance", marks: 2 },
      { id: "p3-a8", questionNumber: 8, question: "A lockout occurs when...", questionAf: "'n Uitsluiting vind plaas wanneer...", options: [{ label: "A", text: "Workers refuse to work", textAf: "Werkers weier om te werk" }, { label: "B", text: "An employer prevents workers from entering the workplace", textAf: "'n Werkgewer werkers verhoed om die werkplek te betree" }, { label: "C", text: "The business closes permanently", textAf: "Die besigheid permanent sluit" }, { label: "D", text: "Employees work overtime", textAf: "Werknemers oortyd werk" }], correctAnswer: "B", topic: "Legislation", marks: 2 },
      { id: "p3-a9", questionNumber: 9, question: "Strategic planning differs from operational planning because it...", questionAf: "Strategiese beplanning verskil van operasionele beplanning omdat dit...", options: [{ label: "A", text: "Focuses on daily tasks", textAf: "Op daaglikse take fokus" }, { label: "B", text: "Sets long-term direction and vision for the organisation", textAf: "Langtermynrigting en visie vir die organisasie stel" }, { label: "C", text: "Only involves lower management", textAf: "Slegs laer bestuur betrek" }, { label: "D", text: "Is less important", textAf: "Minder belangrik is" }], correctAnswer: "B", topic: "Business Strategies", marks: 2 },
      { id: "p3-a10", questionNumber: 10, question: "The National Credit Act protects consumers from...", questionAf: "Die Nasionale Kredietwet beskerm verbruikers teen...", options: [{ label: "A", text: "High quality products", textAf: "Hoë kwaliteit produkte" }, { label: "B", text: "Reckless lending and over-indebtedness", textAf: "Roekelose lenings en oormatige skuld" }, { label: "C", text: "Employment disputes", textAf: "Indiensnemingsgeskille" }, { label: "D", text: "Environmental damage", textAf: "Omgewingskade" }], correctAnswer: "B", topic: "Legislation", marks: 2 },
      { id: "p3-a11", questionNumber: 11, question: "Benchmarking is best described as...", questionAf: "Maatstafvergelyking word die beste beskryf as...", options: [{ label: "A", text: "Setting low standards to easily achieve goals", textAf: "Om lae standaarde te stel om doelwitte maklik te bereik" }, { label: "B", text: "Comparing business practices against industry best standards", textAf: "Om besigheidspraktyke te vergelyk met die beste bedryfsstandaarde" }, { label: "C", text: "Copying competitor products", textAf: "Om mededingerproduk te kopieer" }, { label: "D", text: "Reducing quality to save costs", textAf: "Om kwaliteit te verminder om koste te bespaar" }], correctAnswer: "B", topic: "Quality of Performance", marks: 2 },
      { id: "p3-a12", questionNumber: 12, question: "Workplace diversity refers to...", questionAf: "Werkplekdiversiteit verwys na...", options: [{ label: "A", text: "Having only one type of employee", textAf: "Om slegs een tipe werknemer te hê" }, { label: "B", text: "Employing people from different backgrounds, cultures and abilities", textAf: "Om mense van verskillende agtergronde, kulture en vermoëns in diens te neem" }, { label: "C", text: "Reducing the workforce", textAf: "Om die arbeidsmag te verminder" }, { label: "D", text: "Hiring only experienced workers", textAf: "Om slegs ervare werkers aan te stel" }], correctAnswer: "B", topic: "Human Resources", marks: 2 },
      { id: "p3-a13", questionNumber: 13, question: "A SWOT analysis helps a business to...", questionAf: "'n SWOT-ontleding help 'n besigheid om...", options: [{ label: "A", text: "Only identify weaknesses", textAf: "Slegs swakpunte te identifiseer" }, { label: "B", text: "Identify strengths, weaknesses, opportunities and threats for strategic planning", textAf: "Sterkpunte, swakpunte, geleenthede en bedreigings vir strategiese beplanning te identifiseer" }, { label: "C", text: "Replace financial analysis", textAf: "Finansiële ontleding te vervang" }, { label: "D", text: "Eliminate competition", textAf: "Mededinging uit te skakel" }], correctAnswer: "B", topic: "Business Strategies", marks: 2 },
      { id: "p3-a14", questionNumber: 14, question: "The Occupational Health and Safety Act requires employers to...", questionAf: "Die Wet op Beroepsgesondheid en Veiligheid vereis dat werkgewers...", options: [{ label: "A", text: "Provide entertainment for workers", textAf: "Vermaak vir werkers verskaf" }, { label: "B", text: "Ensure a safe and healthy working environment", textAf: "'n Veilige en gesonde werksomgewing verseker" }, { label: "C", text: "Allow unlimited leave", textAf: "Onbeperkte verlof toelaat" }, { label: "D", text: "Pay for workers' education", textAf: "Vir werkers se onderwys betaal" }], correctAnswer: "B", topic: "Legislation", marks: 2 },
      { id: "p3-a15", questionNumber: 15, question: "Emotional intelligence in leadership involves...", questionAf: "Emosionele intelligensie in leierskap behels...", options: [{ label: "A", text: "Ignoring emotions in the workplace", textAf: "Om emosies in die werkplek te ignoreer" }, { label: "B", text: "Understanding and managing your own emotions and those of others", textAf: "Om jou eie emosies en dié van ander te verstaan en te bestuur" }, { label: "C", text: "Being emotional at work", textAf: "Om emosioneel by die werk te wees" }, { label: "D", text: "Avoiding conflict at all costs", textAf: "Om konflik ten alle koste te vermy" }], correctAnswer: "B", topic: "Leadership & Management", marks: 2 },
      { id: "p3-a16", questionNumber: 16, question: "Triple bottom line reporting measures...", questionAf: "Drieledige botlynverslagdoening meet...", options: [{ label: "A", text: "Only financial performance", textAf: "Slegs finansiële prestasie" }, { label: "B", text: "People, planet and profit performance", textAf: "Mense-, planeet- en winsprestasie" }, { label: "C", text: "Only environmental impact", textAf: "Slegs omgewingsimpak" }, { label: "D", text: "Staff satisfaction only", textAf: "Slegs personeeltevredenheid" }], correctAnswer: "B", topic: "Ethics, Professionalism & Corporate Governance", marks: 2 },
      { id: "p3-a17", questionNumber: 17, question: "The UIF provides workers with...", questionAf: "Die WVF voorsien werkers van...", options: [{ label: "A", text: "Permanent employment", textAf: "Permanente indiensneming" }, { label: "B", text: "Short-term financial relief during unemployment, illness or maternity", textAf: "Korttermyn finansiële verligting tydens werkloosheid, siekte of kraam" }, { label: "C", text: "Housing allowances", textAf: "Behuisingstoelae" }, { label: "D", text: "Retirement pension", textAf: "Aftreepensioen" }], correctAnswer: "B", topic: "Legislation", marks: 2 },
      { id: "p3-a18", questionNumber: 18, question: "A vision statement describes...", questionAf: "'n Visiestelling beskryf...", options: [{ label: "A", text: "The company's daily operations", textAf: "Die maatskappy se daaglikse bedrywighede" }, { label: "B", text: "Where the business aspires to be in the future", textAf: "Waar die besigheid in die toekoms wil wees" }, { label: "C", text: "The current financial position", textAf: "Die huidige finansiële posisie" }, { label: "D", text: "Employee job descriptions", textAf: "Werknemerposkrywings" }], correctAnswer: "B", topic: "Business Strategies", marks: 2 },
      { id: "p3-a19", questionNumber: 19, question: "Whistleblowing in a business context means...", questionAf: "Fluitjieblasery in 'n besigheidskonteks beteken...", options: [{ label: "A", text: "Promoting the company publicly", textAf: "Om die maatskappy openlik te bevorder" }, { label: "B", text: "Reporting unethical or illegal activities within the organisation", textAf: "Om onetiese of onwettige aktiwiteite binne die organisasie aan te meld" }, { label: "C", text: "Marketing to competitors", textAf: "Om aan mededingers te bemark" }, { label: "D", text: "Sharing trade secrets", textAf: "Om handelsgeheime te deel" }], correctAnswer: "B", topic: "Ethics, Professionalism & Corporate Governance", marks: 2 },
      { id: "p3-a20", questionNumber: 20, question: "Performance appraisal is important because it...", questionAf: "Prestasie-evaluering is belangrik omdat dit...", options: [{ label: "A", text: "Is used only to dismiss workers", textAf: "Slegs gebruik word om werkers te ontslaan" }, { label: "B", text: "Measures employee performance and identifies areas for development", textAf: "Werknemerprestasie meet en areas vir ontwikkeling identifiseer" }, { label: "C", text: "Replaces salary negotiations", textAf: "Salarisonderhandelinge vervang" }, { label: "D", text: "Is required by law monthly", textAf: "Maandeliks deur die wet vereis word" }], correctAnswer: "B", topic: "Human Resources", marks: 2 }
